# -*- coding: utf-8 -*-
from _lib import *
MM='Manuel des Monstres 5e (2014)'
I(1,'Dans D&D 5e, lequel de ces monstres peut voler ?','Gargouille',['Ankheg','Bulette','Roper'],'La gargouille a des ailes et vole. L’ankheg, le bulette et le roper restent au sol ou sous terre.',MM+', entrées correspondantes')
I(2,'Dans D&D 5e, lequel de ces monstres ne pétrifie pas ses proies ?','Rouilleur',['Basilic','Cockatrice','Gorgone'],'Le rouilleur ronge le métal. Basilic (regard), cockatrice (morsure) et gorgone (souffle) pétrifient.',MM+', entrées correspondantes')
I(3,'Dans D&D 5e, lequel de ces monstres n’est pas une vase (ooze) ?','Mimique',['Cube gélatineux','Pudding noir','Limon gris'],'Le mimique est une monstruosité ; cube gélatineux, pudding noir et limon gris sont des vases.',MM+', entrées correspondantes')
T(1,'Dans D&D 5e, le ____ gélatineux est un monstre de donjon transparent qui engloutit ses proies.','cube',['sphère','pyramide','prisme'],'Le cube gélatineux balaie les couloirs de donjon en absorbant tout ce qu’il rencontre.',MM+', entrée « Cube gélatineux »')
T(1,'Dans D&D 5e, le ____ ronge les armes et les armures en métal.','rouilleur',['stirge','piercer','roper'],'Le rouilleur (rust monster) corrode le métal qui le touche.',MM+', entrée « Rouilleur »')
T(3,'Dans les Royaumes Oubliés, le mégadonjon d’____ s’étend sous la cité de Waterdeep.','Undermountain',['Menzoberranzan','Mithral Hall','Gracklstugh'],'Undermountain, domaine du mage Halaster Blackcloak, se trouve sous Waterdeep.','Waterdeep: Dungeon of the Mad Mage (2018)')
M(3,'Dans D&D 5e, lesquels de ces monstres ont un FP d’au moins 5 ? (plusieurs bonnes réponses)',['Roper','Bulette','Ver pourpre'],['Cube gélatineux','Stirge'],'FP : roper 5, bulette 5, ver pourpre 15 ; cube gélatineux 2 et stirge 1/8.',MM+', blocs de caractéristiques')
M(2,'Dans D&D 5e, lesquels de ces monstres se font passer pour un élément du décor ? (plusieurs bonnes réponses)',['Mimique','Roper','Piercer'],['Displacer beast','Ankheg'],'Le mimique, le roper et le piercer attendent leurs proies sous une fausse apparence.',MM+', entrées correspondantes')
M(3,'Dans D&D 5e, lesquels de ces monstres ont un FP de 2 ? (plusieurs bonnes réponses)',['Cube gélatineux','Mimique','Gargouille'],['Basilic','Hibours'],'Cube gélatineux, mimique et gargouille valent FP 2 ; basilic et hibours FP 3.',MM+', blocs de caractéristiques')
O(3,'Classe ces monstres par FP croissant.',['Rouilleur','Hibours','Roper','Ver pourpre','Tarasque'],'FP : rouilleur 1/2, hibours 3, roper 5, ver pourpre 15, tarasque 30.',MM+', blocs de caractéristiques')
O(3,'Classe ces monstres par points de vie moyens croissants.',['Stirge','Rouilleur','Hibours','Cube gélatineux','Tarasque'],'PV moyens : stirge 2, rouilleur 27, hibours 59, cube gélatineux 84, tarasque 676.',MM+', blocs de caractéristiques')
A(1,'Associe chaque monstre à sa particularité.',[('Cube gélatineux','Presque transparent'),('Mimique','Imite un coffre'),('Rouilleur','Ronge le métal'),('Basilic','Regard pétrifiant')],'Chaque monstre de donjon a sa marque : transparence, déguisement, corrosion, pétrification.',MM+', entrées correspondantes')
A(2,'Associe chaque monstre à sa description.',[('Hibours','Hybride hibou et ours'),('Cockatrice','Mi-coq, mi-lézard'),('Stirge','Buveur de sang volant'),('Bulette','Requin des terres')],'Hibours, cockatrice, stirge et bulette ont chacun une silhouette bien reconnaissable.',MM+', entrées correspondantes')
W(1,['Je suis presque invisible.','Je glisse dans les couloirs en avalant tout sur mon passage.','Mon corps est un cube de gelée de trois mètres de côté.'],'Cube gélatineux',['Pudding noir','Limon gris','Mimique'],'Le cube gélatineux est une vase transparente, hôte classique des donjons.',MM+', entrée « Cube gélatineux »')
W(2,['Je suis un maître du déguisement.','Je ressemble à un coffre, une porte ou un escalier.','Je colle à ma proie avec une substance adhésive.'],'Mimique',['Roper','Piercer','Cube gélatineux'],'Le mimique se fait passer pour un objet banal, puis colle ses victimes.',MM+', entrée « Mimique »')
W(2,['Je suis le monstre le plus redoutable du Manuel des Monstres.','Ma légende vient de la ville de Tarascon.','Mon FP est de 30.'],'Tarasque',['Ver pourpre','Bulette','Gorgone'],'La tarasque (FP 30) est inspirée d’une légende provençale.',MM+', entrée « Tarasque »')
W(2,['Je suis le fruit d’un croisement magique.','J’ai le plumage d’un hibou et la force d’un ours.','J’étreins mes victimes avec mes griffes.'],'Hibours',['Displacer beast','Griffon','Manticore'],'Le hibours est un hybride de hibou et d’ours, féroce et territorial.',MM+', entrée « Hibours »')
save('monstres-donjon','don')
